INF = float('inf')
class LiChao:
    def __init__(self, x_max={{x_max}}):
        self.X = x_max
        self.tree = [None]*(4*x_max)
    def f(self, line, x): return line[0]*x + line[1]
    def insert(self, line, p=1, l=0, r=None):
        if r is None: r = self.X-1
        if self.tree[p] is None: self.tree[p] = line; return
        m = (l+r)//2
        lo_new = self.f(line, l) < self.f(self.tree[p], l)
        mi_new = self.f(line, m) < self.f(self.tree[p], m)
        if mi_new: self.tree[p], line = line, self.tree[p]
        if l == r: return
        if lo_new != mi_new: self.insert(line, 2*p, l, m)
        else: self.insert(line, 2*p+1, m+1, r)
    def query(self, x, p=1, l=0, r=None):
        if r is None: r = self.X-1
        if self.tree[p] is None: return INF
        res = self.f(self.tree[p], x)
        if l == r: return res
        m = (l+r)//2
        if x <= m: return min(res, self.query(x, 2*p, l, m))
        return min(res, self.query(x, 2*p+1, m+1, r))
